const resolveAll = (table) => Object.fromEntries(Object.entries(table).map(([key, markup]) => [key, resolveAssets(markup)]));

export const OFFER_ARTWORK = resolveAll(offerArtwork);
export const PROOF_ARTWORK = resolveAll(proofArtwork);

const escapeHtml = (value) => String(value ?? "").replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));

export const fillArtwork = (markup, values) =>
  markup.replace(/\{\{(\w+)\}\}/g, (_, name) => escapeHtml(values[name]));
